import { useEffect, useMemo, useState, type ReactNode } from "react";
import { DueCueWordmark } from "./components/DueCueMark";
import { buildTodayPlan, buildWeeklyGamePlan, calculateTaskRisk, detectWorkloadRadar, findBatchSuggestions, recommendForAvailableTime } from "./intelligence";

const API = import.meta.env.VITE_API_BASE_URL ?? "";
type Page = "home" | "work" | "import" | "calendar" | "reminders";
type Task = { id: string; providerId: string; title: string; type: string; dueAt: string; pointsPossible: number | null; status: string; estimatedMinutes: number | null; difficulty: "low" | "medium" | "high"; course: { id: string; code: string; color: string; name: string; difficulty: "easy" | "normal" | "hard"; currentGradePercent: number | null; targetGradePercent: number | null; courseImportance: "normal" | "important" | "critical"; gradeGoalLabel: string | null; gradeDataSource: "manual" | "future_canvas" | "unknown" }; recommendations: Array<{ id: string; recommendedStartAt: string; priorityScore: number; confidenceScore: number; explanation: string }> };
type DashboardData = { tasks: Task[]; events: Array<{ id: string; eventType: string; createdAt: string; task: { title: string } }> };

const date = (value: string) => new Date(value).toLocaleDateString(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
async function api<T>(path: string, options?: RequestInit): Promise<T> {
  const endpoint = `${API}/api${path}`;
  try {
    const response = await fetch(endpoint, { headers: { "Content-Type": "application/json", ...(options?.headers ?? {}) }, ...options });
    if (!response.ok) { const payload = await response.json().catch(() => ({ error: response.statusText })); throw new Error(`${response.status} ${response.statusText} at ${endpoint}: ${payload.error ?? "Request failed"}`); }
    return response.json();
  } catch (error) {
    if (error instanceof TypeError) throw new Error(`Network request failed for ${endpoint}. Check that the DueCue API is running and VITE_API_BASE_URL is correct. (${error.message})`);
    throw error;
  }
}

export default function App() {
  const [page, setPage] = useState<Page>("home"); const [data, setData] = useState<DashboardData>({ tasks: [], events: [] }); const [loading, setLoading] = useState(true); const [notice, setNotice] = useState(""); const [stage, setStage] = useState(1); const [selected, setSelected] = useState<Task | null>(null); const [onboarding, setOnboarding] = useState(false); const feedbackQuery = new URLSearchParams(window.location.search); const emailFeedback = feedbackQuery.get("emailFeedback"); const emailTask = feedbackQuery.get("task");
  const load = async () => { setLoading(true); try { const [taskResult, demo] = await Promise.all([api<{ tasks: Task[] }>("/tasks"), api<{ recentEvents: DashboardData["events"]; mockStage: number }>("/demo/state")]); setData({ tasks: taskResult.tasks, events: demo.recentEvents }); setStage(demo.mockStage); } catch (error) { setNotice(error instanceof Error ? error.message : "Could not reach the DueCue API."); } finally { setLoading(false); } };
  useEffect(() => { void load(); void api<{ user: { settings: { onboardingCompleted: boolean } } }>("/me").then((value) => setOnboarding(!value.user.settings.onboardingCompleted)).catch(() => undefined); }, []);
  const runSync = async () => { const next = stage >= 4 ? 1 : stage + 1; try { await api("/sync/run", { method: "POST", body: JSON.stringify({ stage: next }) }); setNotice(`Sync pulse complete — demo stage ${next} applied.`); await load(); } catch (error) { setNotice(error instanceof Error ? error.message : "Sync failed."); } };
  const resetDemo = async () => { try { await api("/demo/reset", { method: "POST" }); setNotice("Demo workspace reset to stage 1."); await load(); } catch (error) { setNotice(error instanceof Error ? error.message : "Demo reset failed."); } };
  const startNow = data.tasks.filter((task) => task.status === "start_now" || task.status === "overdue"); const dueSoon = data.tasks.filter((task) => new Date(task.dueAt).getTime() < Date.now() + 7 * 86_400_000 && task.status !== "done");
  const nextChange = ["New CSE project appears", "MATH quiz moves earlier", "English essay points increase", "Return to the baseline workload"][stage - 1];
  if (loading) return <div className="loading">Loading your DueCue workspace…</div>;
  if (emailFeedback) return <EmailFeedbackConfirmation state={emailFeedback} task={emailTask} />;
  return <div className="app-shell"><aside><button className="brand" onClick={() => setPage("home")}><DueCueWordmark compact /></button><p className="demo-label">Student workspace</p><nav>{(["home", "work", "import", "calendar", "reminders"] as Page[]).map((item) => <button key={item} className={page === item ? "active" : ""} onClick={() => setPage(item)}>{item[0].toUpperCase() + item.slice(1)}</button>)}</nav><div className="demo-status"><span>Demo workspace</span><b>Stage {stage} of 4</b><p>Simulated CarmenCanvas-style data<br />Next: {nextChange}</p><div className="sidebar-today"><span>Today</span><b>{startNow.length} to start · {dueSoon.length} due soon</b></div><button className="demo-reset" onClick={resetDemo}>Reset recruiter demo</button></div></aside><main className="content"><header className="topbar"><div className="topbar-context"><span>{page.toUpperCase()}</span><b>{page === "home" ? "Academic command center" : page === "reminders" ? "Notification settings" : "Student workspace"}</b></div><div className="sync-control"><button className="sync-button" onClick={runSync}><span>↻</span> Run demo sync</button><small>Next: {nextChange}</small></div></header><div className="page-intro"><h1>{page === "home" ? "Hi, Jace" : page === "work" ? "Your coursework" : page === "reminders" ? "Reminders" : page[0].toUpperCase() + page.slice(1)}</h1>{page === "home" && <p>You have {startNow.length} {startNow.length === 1 ? "thing" : "things"} worth starting today and {dueSoon.length} due this week.</p>}{page === "reminders" && <p>Choose who DueCue notifies when coursework is approaching.</p>}</div>{notice && <div className="notice"><span>{notice}</span><button onClick={() => setNotice("")}>×</button></div>}{page === "home" && <Home tasks={data.tasks} events={data.events} startNow={startNow} dueSoon={dueSoon} nextChange={nextChange} onSelect={setSelected} />}{page === "work" && <Work tasks={data.tasks} onSelect={setSelected} />}{page === "import" && <Import onImported={load} />}{page === "calendar" && <Calendar tasks={data.tasks} onSelect={setSelected} />}{page === "reminders" && <><RemindersIntro /><NotificationPreferences /><Notifications tasks={data.tasks} /></>}</main>{selected && <TaskModal task={selected} close={() => setSelected(null)} refresh={load} />}{onboarding && <Onboarding complete={() => setOnboarding(false)} />}</div>;
}

function EmailFeedbackConfirmation({ state, task }: { state: string; task: string | null }) { const ok = state === "recorded"; return <main className="email-feedback-page"><DueCueWordmark compact /><h1>{ok ? "Got it — DueCue will adjust future cues like this." : state === "expired" ? "This feedback link has already been used or expired." : "That feedback link is not valid."}</h1><p>{ok ? `${task ? `Your feedback for ${task} was saved. ` : ""}Thanks for helping make your timing more useful.` : "No changes were made to your DueCue preferences."}</p><a href="/">Back to DueCue</a></main>; }

function Home({ tasks, events, startNow, dueSoon, nextChange, onSelect }: { tasks: Task[]; events: DashboardData["events"]; startNow: Task[]; dueSoon: Task[]; nextChange: string; onSelect: (task: Task) => void }) {
  const changedTitles = events.filter((event) => event.eventType !== "created").map((event) => event.task.title);
  const plan = buildTodayPlan(tasks, changedTitles).map((entry) => { const gap = entry.task.course.targetGradePercent != null && entry.task.course.currentGradePercent != null ? entry.task.course.targetGradePercent - entry.task.course.currentGradePercent : 0; return gap > 0 ? { ...entry, reason: `${entry.reason} ${entry.task.course.code} is ${gap}% below your target grade.` } : entry; }).slice(0, 4); const primary = plan[0]?.task ?? startNow[0] ?? dueSoon[0];
  const radar = detectWorkloadRadar(tasks, changedTitles); const weekly = buildWeeklyGamePlan(tasks, changedTitles); const batches = findBatchSuggestions(tasks); const [minutes, setMinutes] = useState(60); const timeMatches = recommendForAvailableTime(tasks, minutes, changedTitles).slice(0, 2);
  return <>
    <section className="today-plan ranked-plan"><div className="today-plan-heading"><span className="circle-icon">✦</span><div><h2>Today’s Plan</h2><p>DueCue ranks the work that deserves your attention first—not just what is due first.</p></div><span className="plan-count">{plan.length} cues</span></div><div className="ranked-list">{plan.map(({ task, risk, reason }, index) => <button key={task.id} className="plan-item" onClick={() => onSelect(task)}><strong>{index + 1}</strong><div><b>{task.title}</b><span className="task-badges"><em>{task.course.code}</em><em>{task.type}</em><em className={`risk-pill ${risk.label.toLowerCase().replace(" ", "-")}`}>{risk.label}</em></span><p>{reason}</p></div><dl><div><dt>Due</dt><dd>{date(task.dueAt)}</dd></div><div><dt>Effort</dt><dd>{task.estimatedMinutes ? `${task.estimatedMinutes} min` : "Estimate needed"}</dd></div><div><dt>Cue</dt><dd>{task.recommendations[0]?.priorityScore ?? "—"}/100</dd></div></dl><span className="open-task">Open →</span></button>)}{!plan.length && <Empty text="No high-priority work right now. DueCue will keep watching." />}</div></section>
    <section className="next-cue module urgent">{primary ? <><div className="module-heading"><span className="circle-icon">◷</span><div><h2>Next Cue</h2><p>Why this is your next best move</p></div><span className="status-pill scarlet">{calculateTaskRisk(primary, tasks, changedTitles).label}</span></div><div className="cue-content"><div className="cue-summary"><h3>{primary.title}</h3><div className="task-badges"><em>{primary.course.code}</em><em>{primary.type}</em></div><p>{primary.recommendations[0]?.explanation ?? "DueCue is preparing this cue."}</p></div><dl><div><dt>Due</dt><dd>{date(primary.dueAt)}</dd></div><div><dt>Start window</dt><dd>{primary.recommendations[0] ? date(primary.recommendations[0].recommendedStartAt) : "Calculating"}</dd></div><div><dt>Cue score</dt><dd><span className="score-pill">{primary.recommendations[0]?.priorityScore ?? "—"}/100</span></dd></div></dl><div className="cue-actions"><button onClick={() => onSelect(primary)}>See why</button><div className="quick-feedback"><span>Was this cue helpful?</span><button onClick={() => onSelect(primary)}>Too early</button><button onClick={() => onSelect(primary)}>About right</button><button onClick={() => onSelect(primary)}>Too late</button></div></div></div></> : <Empty text="Your schedule is clear right now." />}</section>
    <section className="intelligence-grid"><article className={`workload-radar ${radar.level.toLowerCase()}`}><span>WORKLOAD RADAR · {radar.level}</span><h2>{radar.message}</h2><p>{radar.action}</p></article><article className="time-helper"><span>I HAVE…</span><div className="time-buttons">{[[30, "30 min"], [60, "1 hour"], [120, "2 hours"]].map(([value, label]) => <button key={value} className={minutes === value ? "active" : ""} onClick={() => setMinutes(value as number)}>{label}</button>)}</div>{timeMatches[0] ? <button className="time-match" onClick={() => onSelect(timeMatches[0].task)}><b>{timeMatches[0].fit}: {timeMatches[0].task.title}</b><span>{timeMatches[0].reason}</span></button> : <p>No matching work right now—enjoy the break.</p>}</article>{plan.find(({ task }) => task.course.currentGradePercent != null && task.course.targetGradePercent != null && task.course.currentGradePercent < task.course.targetGradePercent) && <article className="academic-signal"><span>ACADEMIC GOAL SIGNAL</span><b>{plan.find(({ task }) => task.course.currentGradePercent != null && task.course.targetGradePercent != null && task.course.currentGradePercent < task.course.targetGradePercent)?.task.course.code} is below target, so its comparable tasks get a bounded priority boost.</b><p>Grade goals are optional and private to your workspace.</p></article>}</section>
    <section className="weekly-game-plan"><header><div><span>WEEKLY GAME PLAN</span><h2>What to know about this week</h2></div><p>Short, specific signals—built from your workload, cues, changes, and goals.</p></header><div>{weekly.map((item, index) => <button key={`${item.title}-${index}`} className={item.kind === "task" ? "weekly-task" : "weekly-note"} onClick={() => item.task && onSelect(item.task)} disabled={!item.task}><b>{index + 1}</b><span><strong>{item.title}</strong><small>{item.detail}</small></span>{item.task && <em>Open →</em>}</button>)}{!weekly.length && <Empty text="This week looks manageable. DueCue will keep watching for changes." />}</div></section>
    {batches.length > 0 && <section className="batch-suggestions"><header><div><span>BATCH SUGGESTIONS</span><h2>Small groups that work better together</h2></div><p>Context carries over, so you can get more done with less switching.</p></header><div className="batch-grid">{batches.map((batch) => <article key={batch.title}><span>{batch.title}</span><h3>{batch.tasks.map((task) => task.title).join(" + ")}</h3><p>{batch.reason}</p><footer><b>{batch.minutes} min total</b><button onClick={() => onSelect(batch.tasks[0])}>Open first task →</button></footer></article>)}</div></section>}
    <section className="portal-tiles"><Stat label="Start today" value={startNow.length} detail="inside your start window" /><Stat label="Due this week" value={dueSoon.length} detail="on your radar" /><Stat label="Active coursework" value={tasks.length} detail="being monitored" /><Stat label="Sync status" value="Ready" detail="demo data connected" /></section>
    <section className="portal-modules"><PortalModule title="Start Today" icon="◷" status={`${startNow.length} cues`} accent="scarlet">{startNow.slice(0, 4).map((task) => <TaskRow key={task.id} task={task} allTasks={tasks} changedTitles={changedTitles} onClick={() => onSelect(task)} />)}{!startNow.length && <Empty text="No tasks are inside their start window yet." />}</PortalModule><PortalModule title="Due This Week" icon="▣" status={`${dueSoon.length} tasks`} accent="silver">{dueSoon.slice(0, 5).map((task) => <TaskRow key={task.id} task={task} allTasks={tasks} changedTitles={changedTitles} onClick={() => onSelect(task)} />)}</PortalModule><PortalModule title="Recent Changes" icon="↻" status="Latest sync" accent="blue">{events.slice(0, 3).map((event) => <div className="event" key={event.id}><i className={event.eventType} /><div><b>{humanEvent(event.eventType)}</b><p>{event.task.title}</p></div><time>{date(event.createdAt)}</time></div>)}</PortalModule><PortalModule title="Learning Signal" icon="◌" status="Adaptive timing" accent="tan"><p className="module-copy">DueCue learns from your feedback and adjusts future timing by task type. Open a cue to mark its timing too early, about right, or too late.</p></PortalModule></section>
  </>;
}
function PortalModule({ title, icon, status, accent, children }: { title: string; icon: string; status: string; accent: string; children: ReactNode }) { return <section className={`portal-module ${accent}`}><header><span className="circle-icon">{icon}</span><h2>{title}</h2><span className="status-pill">{status}</span><b>⌄</b></header><div className="module-body">{children}</div></section>; }
function Stat({ label, value, detail }: { label: string; value: string | number; detail: string }) { return <div className="stat"><span>{label}</span><strong>{value}</strong><small>{detail}</small></div>; }
function TaskRow({ task, onClick, allTasks = [], changedTitles = [] }: { task: Task; onClick: () => void; allTasks?: Task[]; changedTitles?: string[] }) { const rec = task.recommendations[0]; const risk = calculateTaskRisk(task, allTasks, changedTitles); return <button className={`task-row ${task.status}`} onClick={onClick}><i style={{ background: task.course.color }} /><div className="task-primary"><b>{task.title}</b><span className="task-badges"><em>{task.course.code}</em><em>{task.type}</em><em className="task-status">{task.status.replace("_", " ")}</em><em className={`risk-pill ${risk.label.toLowerCase().replace(" ", "-")}`}>{risk.label}</em></span></div><div className="task-metrics"><div><span>Due</span><b>{date(task.dueAt)}</b></div><div><span>Cue score</span><b>{rec ? `${rec.priorityScore}/100` : "—"}</b></div><div><span>Start window</span><b>{rec ? date(rec.recommendedStartAt) : "Calculating"}</b></div></div></button>; }
function Empty({ text }: { text: string }) { return <p className="empty">{text}</p>; }
function humanEvent(event: string) { return ({ created: "New task detected", due_date_changed: "Deadline changed", points_changed: "Task importance changed", removed: "Task removed" } as Record<string, string>)[event] ?? "Task updated"; }

type CourseSummary = { id: string; code: string; name: string; color: string; instructorName: string | null; difficulty: string; courseImportance: "normal" | "important" | "critical"; currentGradePercent: number | null; targetGradePercent: number | null; gradeGoalLabel: string | null; _count: { tasks: number } };
function Courses() { const [courses, setCourses] = useState<CourseSummary[]>([]); const [editing, setEditing] = useState<string | null>(null); const [form, setForm] = useState({ current: "", target: "", importance: "normal" as CourseSummary["courseImportance"] }); const load = () => api<{ courses: CourseSummary[] }>("/courses").then((x) => setCourses(x.courses)); useEffect(() => { void load(); }, []); const begin = (course: CourseSummary) => { setEditing(course.id); setForm({ current: course.currentGradePercent?.toString() ?? "", target: course.targetGradePercent?.toString() ?? "", importance: course.courseImportance }); }; const save = async (course: CourseSummary) => { await api(`/courses/${course.id}`, { method: "PATCH", body: JSON.stringify({ currentGradePercent: form.current ? Number(form.current) : null, targetGradePercent: form.target ? Number(form.target) : null, courseImportance: form.importance, gradeGoalLabel: form.target ? "custom" : null, gradeDataSource: "manual" }) }); setEditing(null); await load(); };
  return <div className="course-grid">{courses.map((course) => { const gap = course.currentGradePercent != null && course.targetGradePercent != null ? course.targetGradePercent - course.currentGradePercent : null; return <article className="course-card grade-course-card" key={course.id}><i style={{ background: course.color }} /><span>{course.code}</span><h2>{course.name}</h2><p>{course.instructorName}</p>{editing === course.id ? <div className="grade-form"><label>Current %<input type="number" min="0" max="100" value={form.current} onChange={(e) => setForm({ ...form, current: e.target.value })} /></label><label>Target %<input type="number" min="0" max="100" value={form.target} onChange={(e) => setForm({ ...form, target: e.target.value })} /></label><label>Importance<select value={form.importance} onChange={(e) => setForm({ ...form, importance: e.target.value as CourseSummary["courseImportance"] })}><option value="normal">Normal</option><option value="important">Important</option><option value="critical">Critical</option></select></label><div><button onClick={() => void save(course)}>Save goal</button><button className="quiet-action" onClick={() => setEditing(null)}>Cancel</button></div></div> : <><div className="grade-indicator">{gap == null ? <b>Add grade goal</b> : <><span>Current <b>{course.currentGradePercent}%</b></span><span>Target <b>{course.targetGradePercent}%</b></span><em className={gap > 0 ? "grade-gap" : "grade-on-track"}>{gap > 0 ? `+${gap}% gap` : "On track"}</em></>}</div><button className="grade-goal-button" onClick={() => begin(course)}>{gap == null ? "Add grade goal" : "Edit grade goal"}</button></>}<footer><b>{course._count.tasks} tasks</b><em>{course.courseImportance}</em></footer></article>; })}</div>; }
function Tasks({ tasks, onSelect }: { tasks: Task[]; onSelect: (task: Task) => void }) {
  const [q, setQ] = useState(""); const [course, setCourse] = useState("all"); const [type, setType] = useState("all"); const [status, setStatus] = useState("all"); const [due, setDue] = useState("all");
  const filtered = useMemo(() => tasks.filter((task) => {
    const dueAt = new Date(task.dueAt).getTime(); const dueMatches = due === "all" || (due === "week" && dueAt < Date.now() + 7 * 86400000) || (due === "later" && dueAt >= Date.now() + 7 * 86400000);
    return (!q || `${task.title} ${task.course.code}`.toLowerCase().includes(q.toLowerCase())) && (course === "all" || task.course.code === course) && (type === "all" || task.type === type) && (status === "all" || task.status === status) && dueMatches;
  }), [tasks, q, course, type, status, due]);
  const courses = [...new Set(tasks.map((task) => task.course.code))]; return <section className="panel"><div className="panel-title"><h3>All monitored work</h3><span>{filtered.length} of {tasks.length} tasks</span></div><div className="filters"><input placeholder="Search tasks or courses" value={q} onChange={(e) => setQ(e.target.value)} /><select value={course} onChange={(e) => setCourse(e.target.value)}><option value="all">All courses</option>{courses.map((item) => <option key={item}>{item}</option>)}</select><select value={type} onChange={(e) => setType(e.target.value)}><option value="all">All types</option>{["assignment", "quiz", "exam", "project", "reading", "discussion", "lab"].map((item) => <option key={item}>{item}</option>)}</select><select value={status} onChange={(e) => setStatus(e.target.value)}><option value="all">All statuses</option>{["upcoming", "start_now", "in_progress", "done", "overdue"].map((item) => <option key={item}>{item}</option>)}</select><select value={due} onChange={(e) => setDue(e.target.value)}><option value="all">Any due date</option><option value="week">Due this week</option><option value="later">Later</option></select></div>{filtered.map((task) => <TaskRow key={task.id} task={task} allTasks={tasks} onClick={() => onSelect(task)} />)}{!filtered.length && <Empty text="No tasks match these filters. Clear a filter or import coursework." />}</section>;
}
function Work({ tasks, onSelect }: { tasks: Task[]; onSelect: (task: Task) => void }) { const startNow = tasks.filter((task) => task.status === "start_now" || task.status === "overdue").length; const dueSoon = tasks.filter((task) => new Date(task.dueAt).getTime() < Date.now() + 7 * 86_400_000 && task.status !== "done").length; const courseCount = new Set(tasks.map((task) => task.course.code)).size; return <div className="workspace-sections"><section><div className="section-heading"><div><p className="eyebrow">COURSEWORK</p><h2>All monitored work</h2></div><span>Search, filter, and open a task to understand its cue.</span></div><div className="work-summary"><span><b>{tasks.length}</b> tasks monitored</span><span><b>{startNow}</b> start today</span><span><b>{dueSoon}</b> due this week</span><span><b>{courseCount}</b> courses</span></div><Tasks tasks={tasks} onSelect={onSelect} /></section><section className="compact-grid"><div><div className="section-heading"><div><p className="eyebrow">COURSES</p><h2>Your classes</h2></div></div><Courses /></div><div><div className="section-heading"><div><p className="eyebrow">REMINDERS</p><h2>Preview queue</h2></div></div><Notifications compact tasks={tasks} /><div className="section-heading insight-heading"><div><p className="eyebrow">LEARNING</p><h2>Your timing signals</h2></div></div><Insights compact /></div></section><section><div className="section-heading"><div><p className="eyebrow">SYNC HISTORY</p><h2>Changes DueCue noticed</h2></div></div><Changes compact /></section></div>; }
function Notifications({ compact = false, tasks = [] }: { compact?: boolean; tasks?: Task[] }) { const [items, setItems] = useState<Array<{ id: string; subject: string; body: string; type: string; createdAt: string; recipient?: { email: string; label: string } | null }>>([]); const load = () => api<{ notifications: typeof items }>("/notifications").then((x) => setItems(x.notifications)); useEffect(() => { void load(); }, []); const shown = compact ? items.slice(0, 2) : items; return <><div className="toolbar"><p>{compact ? "Preview-only. No email is sent." : "Preview-only reminders are safe to explore—no email is sent."}</p><button onClick={async () => { await api("/notifications/generate", { method: "POST" }); await load(); }}>Generate previews</button></div><div className="notification-list">{shown.map((item) => { const task = tasks.find((candidate) => item.subject.includes(candidate.title)); const risk = task ? calculateTaskRisk(task, tasks) : null; return <article className="email" key={item.id}><span>PREVIEW · {item.type.replaceAll("_", " ")}</span><h3>{item.subject}</h3>{risk && <em className={`risk-pill ${risk.label.toLowerCase().replace(" ", "-")}`}>{risk.label}</em>}<p className="recipient-preview">Would notify: {item.recipient ? `${item.recipient.label} · ${item.recipient.email}` : "in-app workspace"}</p>{!compact && <p>{item.body}</p>}<time>{date(item.createdAt)}</time></article>; })}{!items.length && <Empty text="Generate previews after recommendations have been calculated." />}</div></>; }
function Insights({ compact = false }: { compact?: boolean }) { const [insights, setInsights] = useState<Array<{ id: string; label: string; leadTimeAdjustmentDays: number; confidence: number; sampleSize: number }>>([]); useEffect(() => { void api<{ insights: typeof insights }>("/feedback/insights").then((x) => setInsights(x.insights)); }, []); if (compact) return <section className="learning-grid compact-learning">{insights.slice(0, 2).map((item) => <article key={item.id}><span>{item.label}</span><strong>{item.leadTimeAdjustmentDays > 0 ? "+" : ""}{item.leadTimeAdjustmentDays} days</strong><p>{Math.round(item.confidence * 100)}% confidence · {item.sampleSize} signals</p></article>)}{!insights.length && <Empty text="Give feedback on a cue to create a learning signal." />}</section>; return <><section className="insight-hero"><span>ADAPTIVE TIMING</span><h2>Every response makes the next cue more personal.</h2><p>DueCue starts with clear rules, then changes timing only when your feedback supports it.</p></section><section className="learning-grid">{insights.map((item) => <article key={item.id}><span>{item.label}</span><strong>{item.leadTimeAdjustmentDays > 0 ? "+" : ""}{item.leadTimeAdjustmentDays} days</strong><p>{Math.round(item.confidence * 100)}% confidence · {item.sampleSize} signals</p></article>)}{!insights.length && <Empty text="Give feedback on a cue to create your first learning signal." />}</section></>; }
const calendarKind = (type: string) => ({ exam: "exam", test: "exam", quiz: "quiz", project: "project", assignment: "assignment", homework: "assignment", lab: "lab", reading: "reading", discussion: "reading" } as Record<string, string>)[type.toLowerCase()] ?? "assignment";
const calendarKindLabel = (kind: string) => ({ exam: "Exams / tests", quiz: "Quizzes", project: "Projects", assignment: "Assignments", lab: "Labs", reading: "Readings / discussions" } as Record<string, string>)[kind];
function Calendar({ tasks, onSelect }: { tasks: Task[]; onSelect: (task: Task) => void }) {
  const [path, setPath] = useState(""); const [kind, setKind] = useState("all"); const [view, setView] = useState<"due" | "start" | "both">("both");
  const create = async () => { const result = await api<{ feedPath: string }>("/calendar/token", { method: "POST" }); setPath(`${API}${result.feedPath}`); };
  const revoke = async () => { await api("/calendar/token", { method: "DELETE" }); setPath(""); };
  const shown = [...tasks].filter((task) => kind === "all" || calendarKind(task.type) === kind).filter((task) => task.status !== "done").sort((a, b) => +new Date(a.dueAt) - +new Date(b.dueAt));
  const groups = shown.reduce<Record<string, Task[]>>((all, task) => { const key = new Date(task.dueAt).toDateString(); (all[key] ??= []).push(task); return all; }, {});
  return <div className="calendar-page">
    <section className="duecue-calendar">
      <div className="calendar-heading"><div><span>YOUR DUECUE TIMELINE</span><h2>See what is coming, and when to begin.</h2><p>Click any item to understand its cue, timing, and next best step.</p></div><div className="calendar-mode" aria-label="Calendar display"><button className={view === "due" ? "active" : ""} onClick={() => setView("due")}>Due dates</button><button className={view === "start" ? "active" : ""} onClick={() => setView("start")}>Start windows</button><button className={view === "both" ? "active" : ""} onClick={() => setView("both")}>Both</button></div></div>
      <div className="calendar-filters" aria-label="Task type filters"><button className={kind === "all" ? "active" : ""} onClick={() => setKind("all")}>All</button>{["exam", "quiz", "project", "assignment", "lab", "reading"].map((item) => <button key={item} className={`${kind === item ? "active" : ""} ${item}`} onClick={() => setKind(item)}><i />{calendarKindLabel(item)}</button>)}</div>
      <div className="calendar-legend"><span><i className="exam" /> Exams / tests</span><span><i className="quiz" /> Quizzes</span><span><i className="project" /> Projects</span><span><i className="assignment" /> Assignments</span><span><i className="lab" /> Labs</span><span><i className="reading" /> Readings / discussions</span></div>
      <div className="timeline">{Object.entries(groups).map(([day, dayTasks]) => <section className="timeline-day" key={day}><header><time>{new Date(day).toLocaleDateString(undefined, { weekday: "short" }).toUpperCase()}</time><b>{new Date(day).toLocaleDateString(undefined, { month: "short", day: "numeric" })}</b><span>{dayTasks.length} item{dayTasks.length === 1 ? "" : "s"}</span></header><div>{dayTasks.map((task) => { const rec = task.recommendations[0]; const itemKind = calendarKind(task.type); return <button className={`timeline-item ${itemKind}`} key={task.id} onClick={() => onSelect(task)}><i /><div className="timeline-task"><b>{task.title}</b><span>{task.course.code} · {calendarKindLabel(itemKind)}</span></div>{view !== "start" && <div className="timeline-timing"><span>Due</span><b>{date(task.dueAt)}</b></div>}{view !== "due" && <div className="timeline-timing"><span>Start</span><b>{rec ? date(rec.recommendedStartAt) : "Calculating"}</b></div>}<em>{rec ? `${rec.priorityScore}/100 cue` : "Cue pending"}</em></button>; })}</div></section>)}{!shown.length && <Empty text="No coursework matches this calendar filter." />}</div>
    </section>
    <section className="calendar-card utility-module calendar-export">
      <span>OPTIONAL EXTERNAL CALENDAR</span><h2>Keep DueCue visible outside the app.</h2><p>The timeline above is your planning view. Use a private feed when you want Apple Calendar, Google Calendar, or Outlook to refresh DueCue dates and start windows over time.</p>
      <div className="calendar-grid">
        <article className="calendar-option"><span>ONE-TIME EXPORT</span><h3>Download calendar file</h3><p>A snapshot of your current schedule. It does not auto-update after you download it.</p><a className="secondary-action" href={`${API}/api/calendar/download`}>Download .ics</a></article>
        <article className="calendar-option recommended"><span>RECOMMENDED · SUBSCRIBE ONCE</span><h3>Private calendar feed</h3><p>Generate a private feed, copy its URL, then subscribe in Apple Calendar, Google Calendar, or Outlook. Compatible apps can refresh it over time.</p><ol><li>Generate private feed</li><li>Copy URL</li><li>Subscribe in your calendar app</li></ol><button onClick={create}>Generate private feed</button>{path && <code>{path}</code>}<button className="quiet-action" onClick={revoke}>Revoke feed</button></article>
        <article className="calendar-option calendar-includes"><span>WHAT GETS INCLUDED</span><h3>Only the useful timing</h3><p>Due dates and recommended start windows for assignments, quizzes, tests, projects, labs, readings, and discussions. Private feed URLs are revocable—do not share yours.</p></article>
      </div>
    </section>
  </div>;
}
function RemindersIntro() { return <section className="reminders-intro"><span>PREVIEW-ONLY DELIVERY</span><h2>Keep the right people in the loop.</h2><p>Set your timing style, choose recipients, and preview start-window, due-soon, deadline-change, and weekly-digest messages. Demo mode never sends real email.</p></section>; }
type Recipient = { id: string; email: string; label: string; relationship: "self" | "parent_guardian" | "other"; verifiedAt: string | null; demoVerified: boolean; enabled: boolean; startWindowEnabled: boolean; dueSoonEnabled: boolean; deadlineChangedEnabled: boolean; weeklyDigestEnabled: boolean };
function NotificationPreferences() { const [settings, setSettings] = useState<{ defaultReminderHour: number; reminderStyle: "conservative" | "balanced" | "aggressive"; weekendRemindersEnabled: boolean; digestEnabled: boolean; emailEnabled: boolean } | null>(null); const [recipients, setRecipients] = useState<Recipient[]>([]); const [form, setForm] = useState({ email: "", label: "", relationship: "self" as Recipient["relationship"] }); const [saved, setSaved] = useState(""); const loadRecipients = () => api<{ recipients: Recipient[] }>("/reminder-recipients").then((result) => setRecipients(result.recipients)); useEffect(() => { void api<{ user: { settings: NonNullable<typeof settings> } }>("/me").then((result) => setSettings(result.user.settings)); void loadRecipients(); }, []); const save = async () => { if (!settings) return; await api("/me/settings", { method: "PATCH", body: JSON.stringify(settings) }); setSaved("Preferences saved. Future cues will use this timing style."); }; const add = async () => { try { await api("/reminder-recipients", { method: "POST", body: JSON.stringify({ ...form, enabled: true, startWindowEnabled: true, dueSoonEnabled: true, deadlineChangedEnabled: true, weeklyDigestEnabled: true }) }); setForm({ email: "", label: "", relationship: "self" }); setSaved("Recipient added. Mark it demo-verified to include it in previews."); await loadRecipients(); } catch (error) { setSaved(error instanceof Error ? error.message : "Could not add recipient."); } }; const updateRecipient = async (id: string, patch: Partial<Recipient>) => { await api(`/reminder-recipients/${id}`, { method: "PATCH", body: JSON.stringify(patch) }); await loadRecipients(); }; const verifyDemo = async (id: string) => { await api(`/reminder-recipients/${id}/verify-demo`, { method: "POST" }); setSaved("Recipient marked demo-verified. It can now appear in previews."); await loadRecipients(); }; if (!settings) return null; return <section className="calendar-card preferences-card"><span>NOTIFICATION SETTINGS</span><h2>Where DueCue sends reminders.</h2><p>Signing in identifies your workspace; reminder recipients are separate. Only add recipients you want to receive coursework reminders. Parent/guardian recipients should opt in before receiving reminders.</p><div className="preference-grid"><label>Timing style<select value={settings.reminderStyle} onChange={(event) => setSettings({ ...settings, reminderStyle: event.target.value as typeof settings.reminderStyle })}><option value="conservative">Earlier and cautious</option><option value="balanced">Balanced</option><option value="aggressive">Closer to the deadline</option></select></label><label>Preferred hour<input type="number" min="0" max="23" value={settings.defaultReminderHour} onChange={(event) => setSettings({ ...settings, defaultReminderHour: Number(event.target.value) })} /></label></div><div className="toggle-list"><label><input type="checkbox" checked={settings.weekendRemindersEnabled} onChange={(event) => setSettings({ ...settings, weekendRemindersEnabled: event.target.checked })} /> Allow weekend reminders</label><label><input type="checkbox" checked={settings.digestEnabled} onChange={(event) => setSettings({ ...settings, digestEnabled: event.target.checked })} /> Include a weekly digest</label><label><input type="checkbox" checked={settings.emailEnabled} onChange={(event) => setSettings({ ...settings, emailEnabled: event.target.checked })} /> Enable real email when delivery is configured</label></div><button className="import-button" onClick={save}>Save preferences</button><div className="recipient-settings"><h3>Reminder recipients</h3><p>Your primary email is listed first. Additional recipients remain preview-only until verified.</p>{recipients.map((recipient) => <article className="recipient-card" key={recipient.id}><div><b>{recipient.label}</b><span>{recipient.email} · {recipient.relationship.replace("_", "/")}</span></div><em className={recipient.verifiedAt || recipient.demoVerified ? "verified" : "unverified"}>{recipient.verifiedAt ? "Verified" : recipient.demoVerified ? "Demo verified" : "Not verified"}</em><label className="recipient-enabled"><input type="checkbox" checked={recipient.enabled} onChange={(event) => updateRecipient(recipient.id, { enabled: event.target.checked })} /> Enabled</label><div className="recipient-types"><label><input type="checkbox" checked={recipient.startWindowEnabled} onChange={(event) => updateRecipient(recipient.id, { startWindowEnabled: event.target.checked })} /> Start window</label><label><input type="checkbox" checked={recipient.dueSoonEnabled} onChange={(event) => updateRecipient(recipient.id, { dueSoonEnabled: event.target.checked })} /> Due soon</label><label><input type="checkbox" checked={recipient.deadlineChangedEnabled} onChange={(event) => updateRecipient(recipient.id, { deadlineChangedEnabled: event.target.checked })} /> Changes</label><label><input type="checkbox" checked={recipient.weeklyDigestEnabled} onChange={(event) => updateRecipient(recipient.id, { weeklyDigestEnabled: event.target.checked })} /> Digest</label></div>{!recipient.verifiedAt && !recipient.demoVerified && <button className="quiet-action" onClick={() => verifyDemo(recipient.id)}>Mock verify for demo</button>}</article>)}<div className="recipient-form"><label>Name<input value={form.label} onChange={(event) => setForm({ ...form, label: event.target.value })} placeholder="Mom, Jace, study partner" /></label><label>Email<input value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} placeholder="name@example.com" /></label><label>Relationship<select value={form.relationship} onChange={(event) => setForm({ ...form, relationship: event.target.value as Recipient["relationship"] })}><option value="self">Self</option><option value="parent_guardian">Parent / guardian</option><option value="other">Other</option></select></label><button onClick={add}>Add recipient</button></div></div>{saved && <p className="import-message">{saved}</p>}<small>Demo verification is for preview-only workspaces. Real email delivery requires an independently verified recipient and configured provider.</small></section>; }
function Changes({ compact = false }: { compact?: boolean }) { const [events, setEvents] = useState<Array<{ id: string; eventType: string; previousValue: Record<string, unknown> | null; newValue: Record<string, unknown> | null; createdAt: string; task: { title: string; course: { code: string } } }>>([]); useEffect(() => { void api<{ events: typeof events }>("/sync/changes").then((x) => setEvents(x.events)); }, []); const shown = compact ? events.slice(0, 5) : events; return <section className="panel"><div className="panel-title"><h3>Source changes detected by DueCue</h3><span>{events.length} events</span></div>{shown.map((event) => <article className="change" key={event.id}><i className={event.eventType} /><div><b>{humanEvent(event.eventType)} · {event.task.course.code}</b><h3>{event.task.title}</h3><p>{event.eventType === "due_date_changed" ? `${String(event.previousValue?.dueAt ?? "previous date")} → ${String(event.newValue?.dueAt ?? "new date")}` : event.eventType === "points_changed" ? `${String(event.previousValue?.pointsPossible ?? "—")} → ${String(event.newValue?.pointsPossible ?? "—")} points` : "Recorded from the latest source sync."}</p></div><time>{date(event.createdAt)}</time></article>)}{!events.length && <Empty text="Run the simulated sync or import coursework to see monitored changes here." />}</section>; }
function Import({ onImported }: { onImported: () => Promise<void> }) {
  const [mode, setMode] = useState<"feed" | "json">("feed"); const [feedUrl, setFeedUrl] = useState(""); const [value, setValue] = useState('[\n  {\n    "courseCode": "CSE 2221",\n    "courseName": "Software I",\n    "title": "Project checkpoint",\n    "dueAt": "2026-09-10T23:59:00.000Z",\n    "type": "project",\n    "pointsPossible": 40,\n    "estimatedMinutes": 180\n  }\n]'); const [message, setMessage] = useState(""); const [failed, setFailed] = useState(false);
  const submit = async () => { try { setFailed(false); const result = mode === "json" ? await api<{ imported: number }>("/imports/json", { method: "POST", body: JSON.stringify({ tasks: JSON.parse(value) }) }) : await api<{ imported: number }>("/imports/ical-feed", { method: "POST", body: JSON.stringify({ feedUrl }) }); setMessage(`Imported ${result.imported} task${result.imported === 1 ? "" : "s"}. DueCue recalculated start windows.`); await onImported(); } catch (error) { setFailed(true); setMessage(error instanceof Error ? error.message : "Import failed. Check the feed URL or required fields and try again."); } };
  const help = "Required: courseCode, title, dueAt (ISO date). Optional: courseName, type, pointsPossible, estimatedMinutes, difficulty, description, sourceUrl.";
  return (
    <section className="import-card">
      <span>SAFE COURSEWORK CONNECTION</span><h2>Import brings coursework into DueCue.</h2>
      <p>DueCue does not scrape Canvas, ask for passwords, or collect access tokens. Use demo data or a user-authorized import to turn coursework into cues, reminders, and calendar events.</p>
      <div className="import-story"><div><b>1</b><span>Paste coursework JSON or iCal / ICS</span></div><div><b>2</b><span>DueCue reads task titles and due dates</span></div><div><b>3</b><span>Coursework becomes tracked tasks</span></div><div><b>4</b><span>Start windows and reminders are calculated</span></div></div>
      <h3 className="connection-heading">Connection paths</h3>
      <div className="connection-paths">
        <article><span>DEMO DATA</span><b>Demo workspace</b><p>Explore realistic coursework without connecting an account.</p><em>Available now</em></article>
        <article><span>ICAL FEED SYNC</span><b>Keep coursework current</b><p>Paste a calendar feed URL once so DueCue can check for new coursework while it remains valid.</p><em>Available now</em></article>
        <article><span>MANUAL JSON</span><b>Paste task data</b><p>A secondary option for demos, testing, and advanced users.</p><em>Safe import</em></article>
        <article><span>GOOGLE CALENDAR OAUTH</span><b>One-click calendar connection</b><p>A future opt-in connection for directly creating calendar events.</p><em>Future</em></article>
        <article><span>CANVAS OAUTH</span><b>Official connection</b><p>A future approved integration for full assignment metadata.</p><em>Future</em></article>
      </div>
      <p className="connection-note">Today, DueCue supports demo data and user-authorized calendar feed/import paths. Future OAuth integrations could let students connect Canvas or Google Calendar with one click. DueCue will prioritize the least manual safe option available.</p>
      <section className="import-panel">
        <div className="import-panel-copy"><div><h3>{mode === "feed" ? "Connect an iCal feed" : "Manual JSON import"}</h3><p>{mode === "feed" ? "Paste your calendar feed URL once. DueCue can periodically check it for new coursework while the feed remains valid." : "For demos, testing, or advanced users: paste exported coursework data below."}</p></div><div className="tabs"><button className={mode === "feed" ? "selected" : ""} onClick={() => { setMode("feed"); setMessage(""); }}>iCal feed sync</button><button className={mode === "json" ? "selected" : ""} onClick={() => { setMode("json"); setMessage(""); }}>Manual JSON</button></div></div>
        {mode === "feed" ? <div className="feed-url-field"><label>Calendar feed URL<input type="url" value={feedUrl} onChange={(event) => setFeedUrl(event.target.value)} placeholder="https://calendar.example.edu/feed.ics" /></label><p>Feeds reliably provide titles, due dates, and sometimes a course name or link. They do not reliably include grades, submission status, rubrics, or exact points—enrich task type, effort, difficulty, points, and status afterward to improve your cues.</p></div> : <textarea aria-label="Task JSON" value={value} onChange={(event) => setValue(event.target.value)} spellCheck={false} />}
        <div className="import-panel-footer">{mode === "json" ? <details><summary>Format help</summary><p>{help}</p></details> : <p className="feed-privacy">Your feed URL is stored as user-provided connection data for future syncs. Do not paste passwords or private access tokens.</p>}<button className="import-button" onClick={submit}>{mode === "feed" ? "Connect and sync feed" : "Import tasks"}</button></div>
        {message && <p className={`import-message ${failed ? "error" : "success"}`}>{message}</p>}
      </section>
    </section>
  );
}
function Onboarding({ complete }: { complete: () => void }) { const [schoolName, setSchoolName] = useState("Ohio State–style demo"); const [reminderStyle, setReminderStyle] = useState("balanced"); const save = async () => { await api("/onboarding/complete", { method: "POST", body: JSON.stringify({ schoolName, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone, reminderStyle, defaultReminderHour: 9 }) }); complete(); }; return <div className="modal-wrap"><article className="onboarding"><span>WELCOME TO DUECUE</span><h2>Know what to start before it becomes urgent.</h2><p>Explore OSU-style simulated course data, then use a safe import path when you are ready. DueCue is not an official Ohio State or CarmenCanvas app.</p><label>School or workspace label<input value={schoolName} onChange={(e) => setSchoolName(e.target.value)} /></label><label>How do you prefer to start?<select value={reminderStyle} onChange={(e) => setReminderStyle(e.target.value)}><option value="conservative">Early and conservative</option><option value="balanced">A few days before</option><option value="aggressive">Close to the deadline</option></select></label><button onClick={save}>Open my workspace →</button></article></div>; }
function TaskModal({ task, close, refresh }: { task: Task; close: () => void; refresh: () => Promise<void> }) {
  const [detail, setDetail] = useState<{ events: Array<{ id: string; eventType: string; createdAt: string }>; notifications: Array<{ id: string; subject: string; body: string }>; recommendations: Array<{ id: string; factors?: { factors?: string[] }; recommendedStartAt: string; priorityScore: number; confidenceScore: number; explanation: string }> } | null>(null);
  const [feedbackState, setFeedbackState] = useState<"" | "sending" | "saved" | "error">("");
  const [enrichment, setEnrichment] = useState({ type: task.type, difficulty: task.difficulty, estimatedMinutes: task.estimatedMinutes?.toString() ?? "", pointsPossible: task.pointsPossible?.toString() ?? "", status: task.status === "done" ? "done" : task.status === "in_progress" ? "in_progress" : "upcoming" }); const [enrichmentState, setEnrichmentState] = useState("");
  useEffect(() => { void api<{ task: typeof detail }>(`/tasks/${task.id}`).then((x) => setDetail(x.task)).catch(() => setDetail(null)); }, [task.id]);
  useEffect(() => { const onKeyDown = (event: KeyboardEvent) => { if (event.key === "Escape") close(); }; window.addEventListener("keydown", onKeyDown); return () => window.removeEventListener("keydown", onKeyDown); }, [close]);
  const rec = detail?.recommendations?.[0] ?? task.recommendations[0];
  const factors = detail?.recommendations?.[0]?.factors?.factors ?? ["Task type and remaining time", "Estimated effort and point value", "Course difficulty and workload", "Feedback from your earlier cues"];
  const send = async (feedbackType: string) => { try { setFeedbackState("sending"); await api("/feedback", { method: "POST", body: JSON.stringify({ taskId: task.id, recommendationId: rec?.id, feedbackType }) }); await refresh(); setFeedbackState("saved"); } catch { setFeedbackState("error"); } };
  const saveEnrichment = async () => { try { setEnrichmentState("Saving…"); await api(`/tasks/${task.id}/enrichment`, { method: "PATCH", body: JSON.stringify({ type: enrichment.type, difficulty: enrichment.difficulty, estimatedMinutes: enrichment.estimatedMinutes ? Number(enrichment.estimatedMinutes) : null, pointsPossible: enrichment.pointsPossible ? Number(enrichment.pointsPossible) : null, status: enrichment.status }) }); await refresh(); setEnrichmentState("Saved — your cue was recalculated."); } catch (error) { setEnrichmentState(error instanceof Error ? error.message : "Could not save task details."); } };
  const status = task.status.replaceAll("_", " "); const risk = calculateTaskRisk(task);
  return <div className="modal-wrap drawer-wrap" onMouseDown={close} role="presentation"><article className="modal task-drawer" onMouseDown={(event) => event.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="task-drawer-title"><button className="close" onClick={close} aria-label="Close task details">×</button><header className="drawer-header"><div className="task-badges"><em>{task.course.code}</em><em>{task.type}</em><em className="status-badge">{status}</em><em className={`risk-pill ${risk.label.toLowerCase().replace(" ", "-")}`}>{risk.label}</em></div><h2 id="task-drawer-title">{task.title}</h2><p>{task.course.name} · Due {date(task.dueAt)} · {task.pointsPossible ?? "—"} points</p></header><section className="drawer-overview"><div><span>RECOMMENDED START</span><b>{rec?.recommendedStartAt ? date(rec.recommendedStartAt) : "Calculating"}</b></div><div><span>CUE SCORE</span><b>{rec?.priorityScore ?? "—"}/100</b></div><div><span>RISK</span><b>{risk.label}</b></div></section><section><span>WHY THIS CUE NOW</span><p>{rec?.explanation ?? "DueCue is calculating this timing from the task details and your workspace."}</p><p className="drawer-helper">{risk.reason} DueCue considers the deadline, task type, effort, points, course difficulty, and feedback you give it—then turns those signals into a practical start window.</p><div className="signal-grid"><div><span>EFFORT</span><b>{task.estimatedMinutes ? `${task.estimatedMinutes} min` : "Not set"}</b></div><div><span>POINTS</span><b>{task.pointsPossible ?? "—"}</b></div><div><span>TASK LEVEL</span><b>{task.difficulty}</b></div><div><span>COURSE LOAD</span><b>{task.course.difficulty}</b></div></div><ul className="factor-list">{factors.map((factor) => <li key={factor}>{factor}</li>)}</ul></section>{["ical_feed", "manual_import"].includes(task.providerId) && <section className="task-enrichment"><span>IMPROVE THIS CUE</span><p>Fill in what your calendar feed could not provide. These details immediately improve future start windows.</p><div><label>Type<select value={enrichment.type} onChange={(event) => setEnrichment({ ...enrichment, type: event.target.value })}>{["assignment", "quiz", "exam", "project", "reading", "discussion", "lab", "other"].map((item) => <option key={item}>{item}</option>)}</select></label><label>Difficulty<select value={enrichment.difficulty} onChange={(event) => setEnrichment({ ...enrichment, difficulty: event.target.value as "low" | "medium" | "high" })}><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></label><label>Effort (min)<input type="number" min="1" value={enrichment.estimatedMinutes} onChange={(event) => setEnrichment({ ...enrichment, estimatedMinutes: event.target.value })} /></label><label>Points<input type="number" min="0" value={enrichment.pointsPossible} onChange={(event) => setEnrichment({ ...enrichment, pointsPossible: event.target.value })} /></label><label>Status<select value={enrichment.status} onChange={(event) => setEnrichment({ ...enrichment, status: event.target.value })}><option value="upcoming">Upcoming</option><option value="in_progress">In progress</option><option value="done">Done</option></select></label></div><button onClick={saveEnrichment}>Save and recalculate</button>{enrichmentState && <p>{enrichmentState}</p>}</section>}<section><span>REMINDER PREVIEW</span>{detail?.notifications?.length ? detail.notifications.slice(0, 1).map((item) => <article className="drawer-preview" key={item.id}><b>{item.subject}</b><p>{item.body}</p></article>) : <div className="drawer-empty"><b>No reminder preview yet</b><p>When a reminder is ready, DueCue will show the exact message here before it sends anything.</p></div>}</section><section><span>RECENT SYNC CHANGES</span>{detail?.events?.length ? <div className="drawer-events">{detail.events.slice(0, 3).map((event) => <p key={event.id}><i />{humanEvent(event.eventType)} <small>{date(event.createdAt)}</small></p>)}</div> : <div className="drawer-empty"><b>No changes to report</b><p>This task has stayed the same since DueCue started monitoring it.</p></div>}</section><section className="drawer-feedback"><span>WAS THIS TIMING USEFUL?</span><p>One quick response helps tune future cues for work like this.</p><div className="feedback"><button disabled={feedbackState === "sending"} onClick={() => send("too_early")}>Too early</button><button disabled={feedbackState === "sending"} onClick={() => send("about_right")}>About right</button><button disabled={feedbackState === "sending"} onClick={() => send("too_late")}>Too late</button></div>{feedbackState === "saved" && <p className="feedback-confirmation">Got it — DueCue will adjust future cues like this.</p>}{feedbackState === "error" && <p className="feedback-error">Feedback could not be saved. Please try again.</p>}</section></article></div>;
}
